module TopModule (
    input  logic clk,
    input  logic reset,
    input  logic data,
    output logic start_shifting
);

    // State encoding: 4 states to track the sequence 1101
    typedef enum logic [1:0] {
        S_IDLE   = 2'b00,
        S_1      = 2'b01,
        S_11     = 2'b10,
        S_110    = 2'b11
    } state_type;

    state_type state, next_state;

    // State transition logic (sequential)
    always_ff @(posedge clk or posedge reset) begin
        if (reset)
            state <= S_IDLE;
        else
            state <= next_state;
    end

    // Next-state combinational logic
    always_comb begin
        case (state)
            S_IDLE: begin
                if (data == 1'b1)
                    next_state = S_1;
                else
                    next_state = S_IDLE;
            end
            S_1: begin
                if (data == 1'b1)
                    next_state = S_11;
                else
                    next_state = S_IDLE; // data == 0 resets to looking for first 1
            end
            S_11: begin
                if (data == 1'b0)
                    next_state = S_110;
                else
                    next_state = S_11; // another 1 keeps us in S_11 (overlap potential, but per spec we just progress)
            end
            S_110: begin
                if (data == 1'b1)
                    next_state = S_IDLE; // sequence 1101 found
                else
                    next_state = S_IDLE; // sequence broken
            end
            default: next_state = S_IDLE;
        endcase
    end

    // Output logic: assert start_shifting when sequence 1101 is detected
    // The sequence is found when we are in S_110 and input data is 1
    assign start_shifting = (state == S_110) & (data == 1'b1);

endmodule

