module TopModule(
    input  x,
    input  y,
    output z
);

  // ----- Module A: z = (x ^ y) & x -----
  // Truth table check:
  //   x=0,y=0 => (0^0)&0 = 0
  //   x=0,y=1 => (0^1)&0 = 0
  //   x=1,y=0 => (1^0)&1 = 1
  //   x=1,y=1 => (1^1)&1 = 0
  function automatic logic [1:0] A_func;
    input logic a, b;  // a=x, b=y
    A_func = (a ^ b) & a;
  endfunction

  // ----- Module B (behavioural based on the waveform) -----
  // Waveform analysis:
  //   (x=0,y=0) -> z=1
  //   (x=1,y=0) -> z=0
  //   (x=0,y=1) -> z=0
  //   (x=1,y=1) -> z=1
  // This implements z = (x & y) | (~x & ~y) = x XNOR y
  function automatic logic [1:0] B_func;
    input logic a, b;  // a=x, b=y
    B_func = (a & b) | (~a & ~b);
  endfunction

  // Internal signals
  logic a_out, b_out, or_out, and_out;

  // First A and B submodules
  // (ports are connected to the top-level x and y)
  always_comb begin
    a_out = A_func(x, y);
    b_out = B_func(x, y);
  end

  // OR gate for the first pair
  assign or_out = a_out | b_out;

  // Second A and B submodules
  always_comb begin
    // Re‑use the same functions; the ports are again x and y
    // (synthesis tool will infer two separate instances)
    // We just drive local signals for clarity;
    // the actual netlist will have two A and two B cells.
    // Here we simply compute the same logic.
  end

  // For simulation / synthesis we instantiate the functions as continuous
  // assignments.  To keep the code synthesizable we use assign statements
  // that model the two separate A and B instances.
  assign a_out2 = A_func(x, y);
  assign b_out2 = B_func(x, y);

  // AND gate for the second pair
  assign and_out = a_out2 & b_out2;

  // Final XOR: z = (OR) ^ (AND)
  assign z = or_out ^ and_out;

endmodule

