module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [2:0] {
        IDLE      = 3'b000,
        BYTE1     = 3'b001,
        BYTE2     = 3'b010,
        BYTE3     = 3'b011,
        DONE      = 3'b100
    } state_t;

    state_t state, next_state;

    // Datapath registers to hold the 3 bytes of the current message
    logic [7:0] byte1, byte2, byte3;

    // FSM state transition logic (sequential always block)
    always_ff @(posedge clk) begin
        if (reset) begin
            state    <= IDLE;
            byte1    <= 8'h0;
            byte2    <= 8'h0;
            byte3    <= 8'h0;
            done     <= 1'b0;
        end else begin
            state    <= next_state;
            done     <= 1'b0; // Default: de-assert done

            case (state)
                IDLE: begin
                    // Discard bytes until in[3] is 1
                    if (in[3]) begin
                        next_state <= BYTE1;
                        byte1      <= in;
                    end else begin
                        next_state <= IDLE;
                    end
                end

                BYTE1: begin
                    // Receive second byte
                    next_state <= BYTE2;
                    byte2      <= in;
                end

                BYTE2: begin
                    // Receive third byte
                    next_state <= BYTE3;
                    byte3      <= in;
                end

                BYTE3: begin
                    // All 3 bytes received; assert done in the next cycle
                    next_state <= DONE;
                end

                DONE: begin
                    // done pulse is one cycle wide; return to IDLE
                    next_state <= IDLE;
                end

                default: next_state <= IDLE;
            endcase
        end
    end

    // Output assignment: valid whenever done is asserted
    // out_bytes[23:16] = first byte, out_bytes[15:8] = second, out_bytes[7:0] = third
    always_comb begin
        if (done) begin
            out_bytes = {byte1, byte2, byte3};
        end else begin
            // Don't-care values when done is not asserted
            out_bytes = 24'hxxxxxxxx;
        end
    end

endmodule

