module TopModule (
    input  clk,
    input  reset,
    output ena   // 3 bits: ena[2] for hundreds, ena[1] for tens, ena[0] for ones
    output q     // 16 bits: q[3:0] ones, q[7:4] tens, q[11:8] hundreds, q[15:12] thousands
);

    // Internal 16-bit register for the BCD counter
    reg [15:0] q_reg;

    // Assign outputs
    // q is the 16-bit output, driven by the register
    assign q = q_reg;

    // ena is derived from the carry flags of the BCD digits
    // ena[0] (ones): always enabled to increment tens
    // ena[1] (tens): enabled when ones roll over (reached 9)
    // ena[2] (hundreds): enabled when tens and ones roll over
    assign ena = {q_reg[15], q_reg[11], q_reg[7]};

    // Synchronous always block
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            q_reg <= 16'd0;
        end else begin
            // Increment logic for BCD counter

            // ones digit (q[3:0]): increments every cycle, rolls over at 9
            if (q_reg[3:0] == 4'd9)
                q_reg[3:0] <= 4'd0;
            else
                q_reg[3:0] <= q_reg[3:0] + 1'b1;

            // tens digit (q[7:4]): increments when ones roll over
            if (q_reg[3:0] == 4'd9) begin
                if (q_reg[7:4] == 4'd9)
                    q_reg[7:4] <= 4'd0;
                else
                    q_reg[7:4] <= q_reg[7:4] + 1'b1;
            end

            // hundreds digit (q[11:8]): increments when tens and ones roll over
            if (q_reg[3:0] == 4'd9 && q_reg[7:4] == 4'd9) begin
                if (q_reg[11:8] == 4'd9)
                    q_reg[11:8] <= 4'd0;
                else
                    q_reg[11:8] <= q_reg[11:8] + 1'b1;
            end

            // thousands digit (q[15:12]): increments when hundreds, tens, and ones roll over
            if (q_reg[3:0] == 4'd9 && q_reg[7:4] == 4'd9 && q_reg[11:8] == 4'd9) begin
                if (q_reg[15:12] == 4'd9)
                    q_reg[15:12] <= 4'd0;
                else
                    q_reg[15:12] <= q_reg[15:12] + 1'b1;
            end
        end
    end

endmodule

