    assign walk_left  = walk_l;
    assign walk_right = walk_r;
    assign aaah       = aaah_out;
    assign digging    = dig_out;

    // State register
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state       <= WALKING_LEFT;
            fall_counter <= 0;
            walk_l       <= 1'b1;
            walk_r       <= 1'b0;
            aaah_out     <= 1'b0;
            dig_out      <= 1'b0;
        end else begin
            state       <= next_state;
            // fall_counter logic depends on state transitions
            case (state)
                WALKING_LEFT: begin
                    if (!ground) begin
                        // Start falling
                        next_state <= FALLING;
                        fall_counter <= 1;
                    end else if (bump_left & bump_right) begin
                        // Bumped on both sides - switch direction
                        next_state <= WALKING_RIGHT;
                    end else if (bump_left) begin
                        // Bumped on left - switch to right
                        next_state <= WALKING_RIGHT;
                    end else if (bump_right) begin
                        // Bumped on right - switch to left
                        next_state <= WALKING_LEFT;
                    end else if (dig) begin
                        // Start digging
                        next_state <= DIGGING;
                    end else begin
                        // Continue walking left
                        next_state <= WALKING_LEFT;
                    end
                end
                WALKING_RIGHT: begin
                    if (!ground) begin
                        // Start falling
                        next_state <= FALLING;
                        fall_counter <= 1;
                    end else if (bump_left & bump_right) begin
                        // Bumped on both sides - switch direction
                        next_state <= WALKING_LEFT;
                    end else if (bump_left) begin
                        // Bumped on left - switch to right
                        next_state <= WALKING_RIGHT;
                    end else if (bump_right) begin
                        // Bumped on right - switch to left
                        next_state <= WALKING_LEFT;
                    end else if (dig) begin
                        // Start digging
                        next_state <= DIGGING;
                    end else begin
                        // Continue walking right
                        next_state <= WALKING_RIGHT;
                    end
                end
                FALLING: begin
                    if (ground) begin
                        // Hit ground
                        if (fall_counter == 5'd20) begin
                            // Splatter
                            next_state <= SPLATTERED;
                            fall_counter <= 0;
                        end else begin
                            // Resume walking in same direction
                            // Need to determine direction based on original direction
                            // Since we only have state, we infer direction from 
                            // the fact that we were walking in a direction before falling.
                            // We'll use a separate register to track direction.
                            // For now, we need to remember the walking direction.
                            // Let's add a direction flip-flop.
                            fall_counter <= 0;
                            // Direction will be handled by the walk_l/walk_r registers
                            // Since we don't have direction memory, we'll assume 
                            // the direction is preserved through the fall_counter logic.
                            // Actually, we need to store the direction before falling.
                            // Let's use a separate register for direction.
                        end
                    end else begin
                        // Still falling
                        if (fall_counter < 5'd25) begin
                            fall_counter <= fall_counter + 1;
                        end
                    end
                end
                DIGGING: begin
                    if (!ground) begin
                        // Hit empty space - fall
                        next_state <= FALLING;
                        fall_counter <= 1;
                    end else if (bump_left & bump_right) begin
                        // Bumped on both sides while digging - switch direction
                        // Specification: being bumped while digging has no effect
                        next_state <= DIGGING;
                    end else if (bump_left) begin
                        // Bumped on left while digging - no effect
                        next_state <= DIGGING;
                    end else if (bump_right) begin
                        // Bumped on right while digging - no effect
                        next_state <= DIGGING;
                    end else if (!dig) begin
                        // Stop digging
                        next_state <= WALKING_LEFT; // Resume walking left by default
                    end else begin
                        // Continue digging
                        next_state <= DIGGING;
                    end
                end
                SPLATTERED: begin
                    // Stay splattered forever
                    next_state <= SPLATTERED;
                end
                default: begin
                    next_state <= WALKING_LEFT;
                end
            endcase
            // Update walking direction based on next state
            case (next_state)
                WALKING_LEFT: begin
                    walk_l <= 1'b1;
                    walk_r <= 1'b0;
                end
                WALKING_RIGHT: begin
                    walk_l <= 1'b0;
                    walk_r <= 1'b1;
                end
                FALLING: begin
                    // During fall, maintain previous walking direction
                    // walk_l and walk_r keep their previous values
                end
                DIGGING: begin
                    // During digging, maintain walking direction
                    // walk_l and walk_r keep their previous values
                end
                SPLATTERED: begin
                    walk_l <= 1'b0;
                    walk_r <= 1'b0;
                end
            endcase
            // aaah output - high during falling
            case (next_state)
                FALLING: begin
                    aaah_out <= 1'b1;
                end
                default: begin
                    aaah_out <= 1'b0;
                end
            endcase
            // digging output - high during digging
            case (next_state)
                DIGGING: begin
                    dig_out <= 1'b1;
                end
                default: begin
                    dig_out <= 1'b0;
                end
            endcase
        end
    end

