module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    // Internal signals for sensor decoding
    wire s2 = s[2];
    wire s1 = s[1];
    wire s0 = s[0];

    // State register (2 bits): current water level and previous level
    reg [1:0] state;
    // State encoding:
    // 2'b00: Below s[0] (lowest)
    // 2'b01: Between s[1] and s[0]
    // 2'b10: Between s[2] and s[1]
    // 2'b11: Above s[2] (highest)

    // Combinational logic for state transition
    always @(*) begin
        if (reset) begin
            // Asynchronous reset: go to 'below s[0]' state
            state = 2'b00;
        end else begin
            // Determine new state based on current sensors
            // Priority: Above s[2] > Between s[2]&s[1] > Between s[1]&s[0] > Below s[0]
            if (s2) begin
                // Above or between upper sensors
                if (s1) begin
                    state = 2'b11; // Above s[2]
                end else begin
                    state = 2'b10; // Between s[2] and s[1]
                end
            end else if (s1) begin
                // Between s[1] and s[0]
                state = 2'b01;
            end else begin
                // Below s[0]
                state = 2'b00;
            end
        end
    end

    // Combinational logic for outputs
    // fr0, fr1, fr2, dfr based on current state and level change detection
    // Level change detection: previous level was lower than current level
    // We infer previous level from the state at the previous clock edge.
    // Since we don't have a dedicated flip-flop for "previous state",
    // we use the current state and the fact that reset initializes to low.
    // However, the spec requires "level previous to the last sensor change".
    // We implement a simple state machine that tracks the previous state.

    reg [1:0] prev_state; // Stores the state from the previous cycle

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            prev_state <= 2'b00;
        end else begin
            prev_state <= state;
            state <= state; // State is updated in the always block above, but here we capture it.
            // Note: The 'always @(*)' block updates 'state' based on 's'.
            // The 'always @(posedge clk)' block captures the value.
            // To make this work, we need to restructure: state update on clock, combinational decode.
        end
    end

    // Rethink: The state transition must happen on the clock edge.
    // Let's move the state assignment to the sequential block.

    always @(posedge clk) begin
        if (reset) begin
            state <= 2'b00;
            prev_state <= 2'b00;
        end else begin
            prev_state <= state;
            // Determine new state
            if (s2) begin
                if (s1) begin
                    state <= 2'b11; // Above s[2]
                end else begin
                    state <= 2'b10; // Between s[2] and s[1]
                end
            end else if (s1) begin
                state <= 2'b01; // Between s[1] and s[0]
            end else begin
                state <= 2'b00; // Below s[0]
            end
        end
    end

    // Assign outputs based on state and level change
    // Level change: previous level was lower than current level.
    // "Lower" means a state number lower in the encoding (00 < 01 < 10 < 11).
    // If current state > prev_state, level rose -> open supplemental valve (dfr=1).
    // If current state <= prev_state, level fell or stayed same -> dfr=0.

    assign fr0 = (state == 2'b01) || (state == 2'b10) || (state == 2'b11) || (state == 2'b00); // Always 1 based on table? 
    // Let's check table:
    // Above s[2]: None
    // Between s[2] and s[1]: fr0
    // Between s[1] and s[0]: fr0, fr1
    // Below s[0]: fr0, fr1, fr2
    // Wait, "Above s[2]" says "None". So fr0, fr1, fr2 are 0.
    // "Between s[2] and s[1]": fr0. fr1=0, fr2=0.
    // "Between s[1] and s[0]": fr0, fr1. fr2=0.
    // "Below s[0]": fr0, fr1, fr2. All 1.

    // Let's redefine outputs based on state.
    // State 00 (Below s[0]): fr0=1, fr1=1, fr2=1, dfr=?
    // State 01 (Between s[1] and s[0]): fr0=1, fr1=1, fr2=0, dfr=?
    // State 10 (Between s[2] and s[1]): fr0=1, fr1=0, fr2=0, dfr=?
    // State 11 (Above s[2]): fr0=0, fr1=0, fr2=0, dfr=?

    // Now dfr logic.
    // "If the sensor change indicates that the previous level was lower than the current level, the flow rate should be increased by opening the Supplemental flow valve (controlled by dfr)."
    // So if state transition was upwards (prev_state < state), dfr = 1.
    // Otherwise, dfr = 0? Or does it stay high?
    // "increased by opening" implies it's a control signal. Usually, if condition met, it's 1.
    // Let's assume dfr is 1 if level rose since last change, else 0.
    // But what about reset? "resets the state machine to a state equivalent to if the water level had been low for a long time (no sensors asserted, and all four outputs asserted)."
    // Reset sets state to 00. All outputs asserted -> fr0=1, fr1=1, fr2=1, dfr=1.

    // Let's assign outputs.

    // fr0
    // 1 if state is 01, 10, or 00. 0 if state is 11.
    // Actually, table says:
    // Above s[2] (11): None -> fr0=0
    // Between s[2]&s[1] (10): fr0 -> fr0=1
    // Between s[1]&s[0] (01): fr0, fr1 -> fr0=1
    // Below s[0] (00): fr0, fr1, fr2 -> fr0=1
    assign fr0 = (state != 2'b11);

    // fr1
    // Above s[2] (11): None -> fr1=0
    // Between s[2]&s[1] (10): fr0 only -> fr1=0
    // Between s[1]&s[0] (01): fr0, fr1 -> fr1=1
    // Below s[0] (00): fr0, fr1, fr2 -> fr1=1
    assign fr1 = (state == 2'b01) || (state == 2'b00);

    // fr2
    // Above s[2] (11): None -> fr2=0
    // Between s[2]&s[1] (10): fr0 only -> fr2=0
    // Between s[1]&s[0] (01): fr0, fr1 -> fr2=0
    // Below s[0] (00): fr0, fr1, fr2 -> fr2=1
    assign fr2 = (state == 2'b00);

    // dfr
    // Active high when level rises.
    // Level rises if current state > previous state.
    // Also, on reset, dfr should be 1 (all outputs asserted).
    assign dfr = (state > prev_state) | reset;

    // However, the spec says: "If the sensor change indicates that the previous level was lower than the current level, the flow rate should be increased by opening the Supplemental flow valve (controlled by dfr)."
    // This implies dfr=1 when level rises.
    // But what if level stays same or falls? dfr=0.
    // The reset condition: "resets the state machine to a state equivalent to if the water level had been low for a long time (no sensors asserted, and all four outputs asserted)."
    // This means on reset, fr0=1, fr1=1, fr2=1, dfr=1.
    // My assign dfr = (state > prev_state) | reset covers this.
    // But wait, if reset happens, state becomes 00. prev_state also becomes 00 (or is reset).
    // If prev_state is reset to 00, then state (00) > prev_state (00) is false.
    // So dfr would be 0 unless we force it.
    // The spec says reset sets it to "all four outputs asserted".
    // So the `| reset` in the assign is correct for dfr.
    // But we also need to ensure fr1 and fr2 are 1 on reset.
    // My current assign for fr1: (state == 2'b01) || (state == 2'b00).
    // If reset sets state to 00, fr1 = 1. Good.
    // fr2: (state == 2'b00). If reset sets state to 00, fr2 = 1. Good.
    // fr0: (state != 2'b11). If state=00, fr0=1. Good.

    // One detail: "previous to the last sensor change".
    // The `prev_state` register captures the state before the current update.
    // This effectively tracks the level change.

endmodule

