module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding
    typedef enum logic [2:0] {
        STATE_A   = 3'b000,
        STATE_B   = 3'b001,
        STATE_C   = 3'b010,
        STATE_D   = 3'b011,
        STATE_E   = 3'b100, // g=1 active, monitoring y (cycle 1)
        STATE_F   = 3'b101, // g=1 active, monitoring y (cycle 2)
        STATE_G   = 3'b110, // g=0 permanent
        STATE_H   = 3'b111  // g=1 permanent
    } state_t;

    state_t state, next_state;

    // Outputs
    assign f = (state == STATE_B) ? 1'b1 : 1'b0;
    assign g = (state == STATE_D) | (state == STATE_E) | (state == STATE_F) | (state == STATE_H) ? 1'b1 : 1'b0;

    // State register (synchronous reset, active low)
    always_ff @(posedge clk or negedge resetn) begin
        if (!resetn) begin
            state <= STATE_A;
        end else begin
            state <= next_state;
        end
    end

    // Next-state logic
    always_comb begin
        // Default: stay in current state
        next_state = state;

        case (state)
            STATE_A: begin
                // On reset de-assertion, go to STATE_B and assert f for one cycle
                next_state = STATE_B;
            end

            STATE_B: begin
                // Monitor x for pattern 1, 0, 1
                if (x == 1'b1) begin
                    next_state = STATE_C;
                end else begin
                    next_state = STATE_B;
                end
            end

            STATE_C: begin
                // We have seen x=1. Now wait for x=0.
                if (x == 1'b0) begin
                    next_state = STATE_D; 
                end else begin
                    next_state = STATE_B;
                end
            end

            STATE_D: begin
                // We have seen the sequence 1, 0.
                if (x == 1'b1) begin
                    // Pattern 1,0,1 detected.
                    // "g should be set to 1 on the following clock cycle".
                    // We transition to STATE_E where g=1 becomes active next cycle.
                    next_state = STATE_E;
                end else begin
                    // If x is 0 here, the sequence broke. Go back to B.
                    next_state = STATE_B;
                end
            end

            STATE_E: begin
                // g is active (1). Now monitor y for the first cycle window.
                if (y == 1'b1) begin
                    next_state = STATE_H; // g stays 1 permanently
                end else begin
                    next_state = STATE_F; // Start the 2-cycle timeout
                end
            end

            STATE_F: begin
                // We are in the second cycle of the "no y=1" window.
                if (y == 1'b1) begin
                    next_state = STATE_H; // g stays 1
                end else begin
                    next_state = STATE_G; // g goes 0 permanently
                end
            end

            STATE_G: begin
                // g = 0 permanently
                next_state = STATE_G;
            end

            STATE_H: begin
                // g = 1 permanently
                next_state = STATE_H;
            end

            default: next_state = STATE_A;
        endcase
    end

endmodule

