module TopModule(
    input  d,
    input  done_counting,
    input  ack,
    input  state[9:0],   // one-hot encoded state (10 bits)

    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
);

    // --- Next-state assertion logic (one-hot decode) ---
    // We assume exactly one bit in 'state' is high at any time.
    // next_state is derived by inspecting the current state and inputs.

    wire S_val     = state[0];
    wire S1_val    = state[1];
    wire S11_val   = state[2];
    wire S110_val  = state[3];
    wire B0_val    = state[4];
    wire B1_val    = state[5];
    wire B2_val    = state[6];
    wire B3_val    = state[7];
    wire Count_val = state[8];
    wire Wait_val  = state[9];

    // --- Next-state mux / assertion wires ---
    // These wires represent the "next state" being asserted.
    // They are mutually exclusive (only one should be high logically),
    // but we define them individually per specification.

    // S_next: next state is S
    // From diagram: S->S (d=0), S->S1 (d=1), S1->S (d=0), S11->S (d=0), S110->S (d=0), Wait->S (ack=1)
    // Effectively: next=S if (current_S & ~d) | (current_S1 & ~d) | (current_S11 & ~d) | (current_S110 & ~d) | (current_Wait & ack)
    assign S_next = (S_val  & ~d) |
                    (S1_val & ~d) |
                    (S11_val& ~d) |
                    (S110_val& ~d) |
                    (Wait_val& ack);

    // S1_next: next state is S1
    // From diagram: S->S1 (d=1). S1 transitions to S (d=0) or S11 (d=1).
    // So next state is S1 only when current state is S and d==1.
    assign S1_next = S_val & d;

    // S11_next: next state is S11
    // From diagram: S1 -> S11 (d=1), S11 -> S11 (d=1).
    assign S11_next = (S1_val | S11_val) & d;

    // S110_next: next state is S110
    // From diagram: S11 -> S110 (d=0).
    assign S110_next = S11_val & ~d;

    // B0_next: next state is B0
    // From diagram: S110 -> B0 (d=1).
    assign B0_next = S110_val & d;

    // B1_next: next state is B1
    // From diagram: B0 -> B1 (always).
    assign B1_next = B0_val;

    // B2_next: next state is B2
    // From diagram: B1 -> B2 (always).
    assign B2_next = B1_val;

    // B3_next: next state is B3
    // From diagram: B2 -> B3 (always).
    assign B3_next = B2_val;

    // Count_next: next state is Count
    // From diagram: B3 -> Count (always).
    assign Count_next = B3_val;

    // Wait_next: next state is Wait
    // From diagram: Count -> Wait (done_counting=1).
    assign Wait_next = Count_val & done_counting;

    // --- Output logic ---
    // done: output logic
    // From diagram: Wait state has done=1.
    assign done = Wait_val;

    // counting: output logic
    // From diagram: Count state has counting=1.
    assign counting = Count_val;

    // shift_ena: output logic
    // From diagram: B0, B1, B2, B3 have shift_ena=1.
    assign shift_ena = B0_val | B1_val | B2_val | B3_val;

endmodule
